  check('Product rows show their share of the category, identifiers only on a wide rail', / of Public Equity$/.test(await page.getAttribute('#tree .tree-row.depth-1 .trel', 'data-tip')) && await page.$eval('#tree .ident', el => getComputedStyle(el).display) === 'none');
