        if (x.reason) return;
        var src = x.riskSources.reduce(function (t, y) { return t + y.contribution; }, 0) + (by === 'factor' ? x.specific : 0), ret = x.returnSources.reduce(function (t, y) { return t + y.contribution; }, 0);
